import{_ as a,C as i,o as l,c,ag as s,E as r,j as t,a as o}from"./chunks/framework.CtWPcAmt.js";const f=JSON.parse('{"title":"Inventory Source Management","description":"","frontmatter":{},"headers":[],"relativePath":"inventory/inventory-source-management.md","filePath":"inventory/inventory-source-management.md","lastUpdated":1787558413000}'),g={name:"inventory/inventory-source-management.md"};function u(d,e,m,h,p,y){const n=i("ImagePopup");return l(),c("div",null,[e[0]||(e[0]=s('<h1 id="inventory-source-management" tabindex="-1">Inventory Source Management <a class="header-anchor" href="#inventory-source-management" aria-label="Permalink to &quot;Inventory Source Management&quot;">​</a></h1><p>An <strong>inventory source</strong> is a place a seller holds stock — a warehouse, a store, or a default location. Each seller manages their own sources, complete with address and contact details, and stock for every product is tracked per source.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>What an inventory source is</li><li>How to create one, field by field</li><li>How sources relate to product stock</li></ul></div><h2 id="your-sources" tabindex="-1">Your sources <a class="header-anchor" href="#your-sources" aria-label="Permalink to &quot;Your sources&quot;">​</a></h2><p>From the Seller Panel, open <strong>Inventories → Inventory Sources</strong>. Every seller starts with a <strong>Default</strong> source and can add more. The list shows each source&#39;s <strong>ID</strong>, <strong>code</strong>, <strong>name</strong>, <strong>priority</strong>, and <strong>status</strong> (Active / Inactive), with <strong>Edit</strong> and <strong>Delete</strong> actions.</p>',5)),r(n,{src:"/images/inventory-source-management/inventory-sources.png",alt:"Seller inventory sources list"}),e[1]||(e[1]=t("h2",{id:"creating-a-source",tabindex:"-1"},[o("Creating a source "),t("a",{class:"header-anchor",href:"#creating-a-source","aria-label":'Permalink to "Creating a source"'},"​")],-1)),e[2]||(e[2]=t("p",null,[o("Select "),t("strong",null,"Create Inventory Source"),o(" and fill in the four sections:")],-1)),r(n,{src:"/images/inventory-source-management/source-create.png",alt:"Create inventory source form"}),e[3]||(e[3]=s('<ul><li><strong>General</strong> — a unique <strong>Code</strong>, a <strong>Name</strong>, and an optional <strong>Description</strong>.</li><li><strong>Address</strong> — <strong>Country</strong>, <strong>State</strong>, <strong>City</strong>, <strong>Street</strong>, and <strong>Postcode</strong>.</li><li><strong>Settings</strong> — <strong>Latitude</strong> / <strong>Longitude</strong> (optional), a <strong>Priority</strong> (which source is drawn from first), and a <strong>Status</strong> toggle.</li><li><strong>Contact Info</strong> — <strong>Contact Name</strong>, <strong>Email</strong>, <strong>Number</strong>, and an optional <strong>Fax</strong>.</li></ul><p>Save it, and the source becomes available when you set stock on products.</p><div class="warning custom-block"><p class="custom-block-title">You can&#39;t delete your only active source</p><p>A source can&#39;t be deleted if it&#39;s the seller&#39;s <strong>only active</strong> source — you always need at least one place to hold stock.</p></div><h2 id="sources-and-stock" tabindex="-1">Sources and stock <a class="header-anchor" href="#sources-and-stock" aria-label="Permalink to &quot;Sources and stock&quot;">​</a></h2><p>Stock is held per source: a product&#39;s quantity is set against a source, and its total availability is the sum across sources. Manage those quantities from <a href="/inventory/manage-inventory">Manage Inventory</a>, or on a product&#39;s <strong>Inventories</strong> tab in <a href="/catalog/product-management#the-product-form">Product Management</a>.</p><h2 id="what-the-admin-sees" tabindex="-1">What the admin sees <a class="header-anchor" href="#what-the-admin-sees" aria-label="Permalink to &quot;What the admin sees&quot;">​</a></h2><p>The admin can review every seller&#39;s sources across the marketplace under <strong>Marketplace → Configure → Inventory Sources</strong>. The list shows each source&#39;s <strong>Id</strong>, <strong>Code</strong>, <strong>Name</strong>, the <strong>Seller Name</strong> and <strong>Business Name</strong> it belongs to, and its <strong>Status</strong>, and each row opens a read-only view with the source&#39;s <strong>General Information</strong>, <strong>Source Address</strong>, <strong>Contact Information</strong>, and <strong>Seller Information</strong>.</p>',7)),r(n,{src:"/images/inventory-source-management/admin-inventory-sources.png",alt:"Admin inventory sources list showing each source against its seller and business name"}),e[4]||(e[4]=t("p",null,"This view is for oversight only — sources are created, edited, and deleted by the seller who owns them.",-1)),e[5]||(e[5]=t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"TIP"),t("p",null,[o("Order your sources by "),t("strong",null,"priority"),o(" the way you actually want them fulfilled — the marketplace draws stock from higher-priority sources first.")])],-1))])}const S=a(g,[["render",u]]);export{f as __pageData,S as default};
